"""One Verse (famous Gita verses) and Vedanta Simply reels for 25 November to 22 December 2026."""
from content_swap_nov import caption

Q_VERSE = ("Which verse should we explain next?", "Welchen Vers sollen wir als Nächstes erklären?")
Q_VEDANTA = ("Which question should we explain next?", "Welche Frage sollen wir als Nächstes erklären?")


def verse_slides(ref, deva, translit, hook, words, says, why_head, why, end_head, cover):
    return [
        {"bg": cover, "label": "One Verse", "blocks": [("deva", deva), ("head", hook), ("translit", translit)]},
        {"bg": "cream", "label": "Word by word", "blocks": [("head", f"Bhagavad Gita {ref}"), ("rule",), ("table", words)]},
        {"bg": "dark", "label": "What it says", "blocks": [("head", "In plain words"), ("body", says)]},
        {"bg": "sand", "label": "Why it matters", "blocks": [("head", why_head), ("body", why)]},
        {"bg": "darkest", "label": "Remember", "center": True, "blocks": [("head", end_head), ("translit", f"Bhagavad Gita {ref}"), ("body", Q_VERSE[0])]},
    ]


def V(ref, deva, translit, hook, hook_de, words, says, why_head, why, end_head, cap_en, cap_de, tags, page, cover="bordeaux", audio="om"):
    return dict(kind="verse", slug=f"gita-{ref.replace('.', '-')}", series="One Verse", topic=f"Gita {ref}", ref=ref,
                deva=deva, translit=translit, hook=hook, hook_de=hook_de, cap_en=cap_en, cap_de=cap_de, page=page, cover=cover, audio=audio,
                slides=verse_slides(ref, deva, translit, hook, words, says, why_head, why, end_head, cover),
                caption=caption(cap_en, cap_de, Q_VERSE, tags))


def vedanta_slides(deva, translit, hook, short_head, short, image_head, image, words, end_head, cover):
    return [
        {"bg": cover, "label": "Vedanta Simply", "blocks": [("deva", deva), ("head", hook), ("translit", translit)]},
        {"bg": "cream", "label": "The short answer", "blocks": [("head", short_head), ("body", short)]},
        {"bg": "dark", "label": "An image", "blocks": [("head", image_head), ("body", image)]},
        {"bg": "sand", "label": "Key words", "blocks": [("head", "Key words"), ("rule",), ("table", words)]},
        {"bg": "darkest", "label": "Take it home", "center": True, "blocks": [("head", end_head), ("translit", translit), ("body", Q_VEDANTA[0])]},
    ]


def D(slug, topic, deva, translit, hook, hook_de, short_head, short, image_head, image, words, end_head, cap_en, cap_de, tags, page, cover="bordeaux", audio="om"):
    return dict(kind="vedanta", slug=slug, series="Vedanta Simply", topic=topic, deva=deva, translit=translit,
                hook=hook, hook_de=hook_de, cap_en=cap_en, cap_de=cap_de, page=page, cover=cover, audio=audio,
                slides=vedanta_slides(deva, translit, hook, short_head, short, image_head, image, words, end_head, cover),
                caption=caption(cap_en, cap_de, Q_VEDANTA, tags))


